import{_ as i,a0 as l,w as o,s as p,ao as d,I as r,x as a,a1 as s,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"在 Linux 中安装 Darkstat：基于网页的流量分析器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中安装 Darkstat：基于网页的流量分析器 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中安装 Darkstat：基于网页的流量分析器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中安装 Darkstat：基于网页的流量分析器 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150811 Darkstat is a Web Based Network Traffic Analyzer--Install it on Linux","title":"在 Linux 中安装 Darkstat：基于网页的流量分析器","tag":"201508","desc":""},"relativePath":"201508/20150811 Darkstat is a Web Based Network Traffic Analyzer--Install it on Linux.md","filePath":"[post].md"}'),u={name:"201508/20150811 Darkstat is a Web Based Network Traffic Analyzer--Install it on Linux.md"};function k(x,t,D,f,m,T){const n=l("Link");return o(),p("div",null,[t[16]||(t[16]=d(`<h1 id="在-linux-中安装-darkstat-基于网页的流量分析器" tabindex="-1">在 Linux 中安装 Darkstat：基于网页的流量分析器 <a class="header-anchor" href="#在-linux-中安装-darkstat-基于网页的流量分析器" aria-label="Permalink to “在 Linux 中安装 Darkstat：基于网页的流量分析器”">​</a></h1><p>Darkstat是一个简易的，基于网页的流量分析程序。它可以在主流的操作系统如Linux、Solaris、MAC、AIX上工作。它以守护进程的形式持续工作在后台，不断地嗅探网络数据，以简单易懂的形式展现在它的网页上。它可以为主机生成流量报告，识别特定的主机上哪些端口是打开的，它兼容IPv6。让我们看下如何在Linux中安装和配置它。</p><h3 id="在linux中安装配置darkstat" tabindex="-1">在Linux中安装配置Darkstat <a class="header-anchor" href="#在linux中安装配置darkstat" aria-label="Permalink to “在Linux中安装配置Darkstat”">​</a></h3><p>** 在Fedora/CentOS/RHEL中安装Darkstat：**</p><p>要在Fedora/RHEL和CentOS中安装，运行下面的命令。</p><pre><code>sudo yum install darkstat
</code></pre><p><strong>在Ubuntu/Debian中安装Darkstat：</strong></p><p>运行下面的命令在Ubuntu和Debian中安装。</p><pre><code>sudo apt-get install darkstat
</code></pre><p>恭喜你，Darkstat已经在你的Linux中安装了。</p><h3 id="配置-darkstat" tabindex="-1">配置 Darkstat <a class="header-anchor" href="#配置-darkstat" aria-label="Permalink to “配置 Darkstat”">​</a></h3><p>为了正确运行这个程序，我们需要执行一些基本的配置。运行下面的命令用gedit编辑器打开/etc/darkstat/init.cfg文件。</p><pre><code>sudo gedit /etc/darkstat/init.cfg
</code></pre><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/13.png" alt=""></p><p><em>编辑 Darkstat</em></p><p>修改START_DARKSTAT这个参数为yes，并在“INTERFACE”中提供你的网络接口。确保取消了DIR、PORT、BINDIP和LOCAL这些参数的注释。如果你希望绑定Darkstat到特定的IP，在BINDIP参数中提供它。</p><h3 id="启动darkstat守护进程" tabindex="-1">启动Darkstat守护进程 <a class="header-anchor" href="#启动darkstat守护进程" aria-label="Permalink to “启动Darkstat守护进程”">​</a></h3><p>安装并配置完Darkstat后，运行下面的命令启动它的守护进程。</p><pre><code>sudo /etc/init.d/darkstat start
</code></pre><p><img src="http://linuxpitstop.com/wp-content/uploads/2015/08/23.png" alt="Restarting Darkstat"></p><p>你可以用下面的命令来在开机时启动Darkstat：</p><pre><code>chkconfig darkstat on
</code></pre>`,22)),r("p",null,[t[1]||(t[1]=a("打开浏览器并打开",-1)),r("strong",null,[s(n,{href:"http://localhost:666"},{default:e(()=>[...t[0]||(t[0]=[a("http://localhost:666",-1)])]),_:1})]),t[2]||(t[2]=a("，它会显示Darkstat的网页界面。使用这个工具来分析你的网络流量。",-1))]),t[17]||(t[17]=r("p",null,[r("img",{src:"http://linuxpitstop.com/wp-content/uploads/2015/08/32.png",alt:"Darkstat"})],-1)),t[18]||(t[18]=r("h3",{id:"总结",tabindex:"-1"},[a("总结 "),r("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[19]||(t[19]=r("p",null,"它是一个占用很少内存的轻量级工具。这个工具流行的原因是简易、易于配置使用。这是一个对系统管理员而言必须拥有的程序。",-1)),t[20]||(t[20]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=a("via: ",-1)),s(n,{href:"http://linuxpitstop.com/install-darkstat-on-ubuntu-linux/"},{default:e(()=>[...t[3]||(t[3]=[a("http://linuxpitstop.com/install-darkstat-on-ubuntu-linux/",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=a("作者：",-1)),s(n,{href:"http://linuxpitstop.com/author/aun/"},{default:e(()=>[...t[5]||(t[5]=[a("Aun",-1)])]),_:1}),t[9]||(t[9]=a(" 译者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[6]||(t[6]=[a("geekpi",-1)])]),_:1}),t[10]||(t[10]=a(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=a("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[a("Linux中国",-1)])]),_:1}),t[15]||(t[15]=a(" 荣誉推出",-1))])])}const C=i(u,[["render",k]]);export{b as __pageData,C as default};
